{
  "meta": {
    "name": "Online Learning Platform",
    "description": "An online learning platform where instructors publish courses and students enroll, complete lessons, and provide reviews, with a freemium model offering access to paid courses and certificates via a premium subscription."
  },
  "entities": [
    {
      "name": "Course",
      "ownable": true,
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "price",
          "type": "number",
          "default": 0
        },
        {
          "name": "isFree",
          "type": "boolean",
          "default": false
        }
      ],
      "relations": [
        {
          "name": "lessons",
          "kind": "oneToMany",
          "target": "Lesson"
        },
        {
          "name": "reviews",
          "kind": "oneToMany",
          "target": "Review"
        }
      ]
    },
    {
      "name": "Lesson",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "videoUrl",
          "type": "url",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ]
    },
    {
      "name": "Enrollment",
      "ownable": true,
      "fields": [
        {
          "name": "enrollmentDate",
          "type": "datetime",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ]
    },
    {
      "name": "LessonCompletion",
      "ownable": true,
      "fields": [
        {
          "name": "completionDate",
          "type": "datetime",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "lesson",
          "kind": "manyToOne",
          "target": "Lesson",
          "required": true
        }
      ]
    },
    {
      "name": "Review",
      "ownable": true,
      "fields": [
        {
          "name": "rating",
          "type": "integer",
          "required": true
        },
        {
          "name": "comment",
          "type": "text"
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "instructor",
      "description": "Can create and manage courses."
    },
    {
      "name": "student",
      "description": "Can enroll in courses, mark lessons complete, and review courses.",
      "isDefault": true
    },
    {
      "name": "premium_subscriber",
      "description": "Has access to paid courses and certificates."
    }
  ],
  "permissions": [
    {
      "role": "instructor",
      "entity": "Course",
      "actions": ["create", "read", "update", "delete"],
      "scope": "own"
    },
    {
      "role": "instructor",
      "entity": "Lesson",
      "actions": ["create", "read", "update", "delete"],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "Enrollment",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "LessonCompletion",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "student",
      "entity": "Course",
      "actions": ["read"],
      "scope": "all",
      "requiresPlan": "free"
    },
    {
      "role": "student",
      "entity": "Enrollment",
      "actions": ["create", "read", "delete"],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "LessonCompletion",
      "actions": ["create", "read"],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "Review",
      "actions": ["create", "read"],
      "scope": "own"
    },
    {
      "role": "premium_subscriber",
      "entity": "Course",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "premium_subscriber",
      "entity": "Enrollment",
      "actions": ["create", "read", "delete"],
      "scope": "own"
    },
    {
      "role": "premium_subscriber",
      "entity": "LessonCompletion",
      "actions": ["create", "read"],
      "scope": "own"
    },
    {
      "role": "premium_subscriber",
      "entity": "Review",
      "actions": ["create", "read"],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "Courses",
      "route": "/courses",
      "type": "list",
      "entity": "Course",
      "access": ["instructor", "student", "premium_subscriber"]
    },
    {
      "name": "Course Detail",
      "route": "/courses/:id",
      "type": "detail",
      "entity": "Course",
      "access": ["instructor", "student", "premium_subscriber"]
    },
    {
      "name": "New Course",
      "route": "/courses/new",
      "type": "form",
      "entity": "Course",
      "access": ["instructor"]
    },
    {
      "name": "Edit Course",
      "route": "/courses/:id/edit",
      "type": "form",
      "entity": "Course",
      "access": ["instructor"]
    },
    {
      "name": "Lessons",
      "route": "/courses/:courseId/lessons",
      "type": "list",
      "entity": "Lesson",
      "access": ["instructor", "student", "premium_subscriber"]
    },
    {
      "name": "New Lesson",
      "route": "/courses/:courseId/lessons/new",
      "type": "form",
      "entity": "Lesson",
      "access": ["instructor"]
    },
    {
      "name": "Edit Lesson",
      "route": "/courses/:courseId/lessons/:id/edit",
      "type": "form",
      "entity": "Lesson",
      "access": ["instructor"]
    },
    {
      "name": "Instructor Dashboard",
      "route": "/dashboard",
      "type": "dashboard",
      "access": ["instructor"],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Students Enrolled",
          "entity": "Enrollment",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Lessons Completed",
          "entity": "LessonCompletion",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Student Dashboard",
      "route": "/student-dashboard",
      "type": "dashboard",
      "access": ["student", "premium_subscriber"],
      "widgets": [
        {
          "type": "table",
          "label": "My Enrollments",
          "entity": "Enrollment"
        },
        {
          "type": "table",
          "label": "My Lesson Completions",
          "entity": "LessonCompletion"
        }
      ]
    },
    {
      "name": "Certificate",
      "route": "/certificate/:courseId",
      "type": "custom",
      "access": ["premium_subscriber"],
      "requiresPlan": "premium"
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "isDefault": true,
      "features": ["access_free_courses"]
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": ["access_paid_courses", "certificates"]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumAccessGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": ["Certificate"],
        "features": ["access_paid_courses", "certificates"]
      }
    },
    {
      "type": "ownership",
      "id": "courseOwnership",
      "entity": "Course"
    },
    {
      "type": "ownership",
      "id": "enrollmentOwnership",
      "entity": "Enrollment"
    },
    {
      "type": "ownership",
      "id": "lessonCompletionOwnership",
      "entity": "LessonCompletion"
    },
    {
      "type": "ownership",
      "id": "reviewOwnership",
      "entity": "Review"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
